sys_script_include.script:
var AjaxForAttachment = Class.create();
AjaxForAttachment.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    getAttachment: function() {

        var sysId = this.getParameter('sysparm_sys_id');

        var parser = new sn_impex.GlideExcelParser();
        var attachment = new GlideSysAttachment();

        var attachmentStream = attachment.getContentStream(sysId);

        parser.parse(attachmentStream);

        var exceldata = {
            headers: [],
            rows: []
        };

        var headers = parser.getColumnHeaders();
        var header1 = headers[0];
        var header2 = headers[1];

        exceldata.headers.push(header1);
        exceldata.headers.push(header2);

        while (parser.next()) {
            var row = parser.getRow();
            var rowData = {};
            rowData[header1] = row[header1];
            rowData[header2] = row[header2];
            exceldata.rows.push(rowData);
        }

        return JSON.stringify(exceldata);
    },

    type: 'AjaxForAttachment'
});
